from typing import List

def maxSizeSlices(slices: List[int]) -> int:
    def dp(arr):
        n = len(arr)
        if n == 0:
            return 0
        dp = [0] * n
        dp[0] = arr[0]
        if n > 1:
            dp[1] = max(arr[0], arr[1])
        for i in range(2, n):
            dp[i] = max(dp[i-1], dp[i-2] + arr[i])
        return dp[-1]

    n = len(slices)
    if n == 3:
        return max(slices)

    # Scenario 1: Pick the first slice, cannot pick the last slice
    scenario1 = dp(slices[:-1])

    # Scenario 2: Do not pick the first slice, can pick the last slice
    scenario2 = dp(slices[1:])

    return max(scenario1, scenario2)

