def unhappyFriends(n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
    # Step 1: Initialize a dictionary to store the pairing of each friend
    pair_dict = {}
    for pair in pairs:
        x, y = pair
        pair_dict[x] = y
        pair_dict[y] = x

    # Step 2: Create a preference rank dictionary
    pref_rank = {}
    for i in range(n):
        pref_rank[i] = {}
        for rank, friend in enumerate(preferences[i]):
            pref_rank[i][friend] = rank

    # Step 3: Initialize a set to keep track of unhappy friends
    unhappy = set()

    # Step 4: Iterate through each pair in the pairs list
    for pair in pairs:
        x, y = pair
        # Check if x is unhappy
        for u in preferences[x]:
            if u == y:
                break
            v = pair_dict[u]
            if pref_rank[u][x] < pref_rank[u][v]:
                unhappy.add(x)
                break
        # Check if y is unhappy
        for u in preferences[y]:
            if u == x:
                break
            v = pair_dict[u]
            if pref_rank[u][y] < pref_rank[u][v]:
                unhappy.add(y)
                break

    # Step 5: Return the count of unhappy friends
    return len(unhappy)

