def minSwaps(grid):
    n = len(grid)
    # Calculate the number of trailing zeros for each row
    trailing_zeros = []
    for row in grid:
        count = 0
        for j in range(n - 1, -1, -1):
            if row[j] == 0:
                count += 1
            else:
                break
        trailing_zeros.append(count)

    res = 0
    # Iterate to find the required trailing zeros for each row
    for i in range(n):
        required = n - 1 - i
        found = -1
        # Look for the first row with enough trailing zeros
        for j in range(i, n):
            if trailing_zeros[j] >= required:
                found = j
                break
        if found == -1:
            return -1
        # Move the found row to position i
        for j in range(found, i, -1):
            trailing_zeros[j], trailing_zeros[j - 1] = trailing_zeros[j - 1], trailing_zeros[j]
            res += 1
    return res

